function openModalUniversal(id){const m=$(id);if(!m)return;if(id==='statsTooltip'){m.classList.add('show');return;}if(id==='sideMenu'){toggleSideMenu(true);return;}pushWindow(id);m.style.display='flex';m.classList.add('show');lockBodyScroll();history.pushState({modal:id,level:windowStack.length},'');history.pushState({modal:id,level:windowStack.length},'');}
