function fetchWithTimeout(url,o={}){const t=o.timeout||5000,c=new AbortController(),tid=setTimeout(()=>{try{c.abort();}catch(e){}},t);return fetch(url,{method:o.method||'GET',headers:o.headers||{},signal:c.signal}).then(r=>{clearTimeout(tid);return r;}).catch(e=>{clearTimeout(tid);throw e;});}
