function applyTheme(mode){darkMode=(mode==='dark');const s=darkMode?DS:LS,r=document.documentElement;Object.keys(s).forEach(k=>r.style.setProperty(k,s[k]));const meta=$('themeColorMeta');if(meta)meta.content=darkMode?'#0d0d0d':'#ebe3d6';const lb=$('themeLight'),db=$('themeDark');if(lb)lb.classList.toggle('active',!darkMode);if(db)db.classList.toggle('active',darkMode);try{localStorage.setItem('darkMode',mode);}catch(e){}r.classList.toggle('dark',darkMode);applyColor(currentColor);applyMushafTheme();debouncedSaveState();}
function applyColor(color){if(!CS[color]){color='gold';}currentColor=color;const s=CS[color][darkMode?'dark':'light'],r=document.documentElement;r.style.setProperty('--gold',s.main);r.style.setProperty('--gold-light',s.light);r.style.setProperty('--gold-dark',s.dark);r.style.setProperty('--gold-rgb',hexToRgb(s.main));localStorage.setItem('accentColor',color);document.querySelectorAll('#colorPicker .color-dot').forEach(d=>d.classList.toggle('active',d.dataset.color===color));}
function loadFontFamily(font){const r=document.documentElement,t=$('fontSelectTrigger');if(font==='system'){currentFont='system';r.style.setProperty('--font-family',"'Traditional Arabic','Arial',sans-serif");r.style.setProperty('--font-ui',"'Tajawal','Arial',sans-serif");if(t)t.textContent='نظام (تقليدي)';document.querySelectorAll('#fontSelectOptions .custom-select-option').forEach(o=>o.classList.toggle('selected',o.dataset.value==='system'));localStorage.setItem('quranFont','system');return;}const lid='google-font-'+font.replace(/\s/g,'');if(!$(lid)){const l=document.createElement('link');l.id=lid;l.rel='stylesheet';l.href='https://fonts.googleapis.com/css2?family='+encodeURIComponent(font)+'&display=swap';document.head.appendChild(l);}currentFont=font;r.style.setProperty('--font-family',"'"+font+"',serif");r.style.setProperty('--font-ui',"'"+font+"',sans-serif");const opts=document.querySelectorAll('#fontSelectOptions .custom-select-option');if(t){const so=Array.from(opts).find(o=>o.dataset.value===font);t.textContent=so?so.textContent:font;}opts.forEach(o=>o.classList.toggle('selected',o.dataset.value===font));localStorage.setItem('quranFont',font);}
function applyScales(){document.documentElement.style.setProperty('--text-scale',textScale);document.documentElement.style.setProperty('--display-scale',displayScale);const tsv=$('textSizeValue'),dsv=$('displaySizeValue');if(tsv)tsv.textContent=Math.round(textScale*100)+'%';if(dsv)dsv.textContent=Math.round(displayScale*100)+'%';localStorage.setItem('textScale',String(textScale));localStorage.setItem('displayScale',String(displayScale));applyMushafFontSize();}
function applyMushafFont(fontId){mushafFont=fontId;localStorage.setItem('mushafFont',fontId);const f=MUSHAF_FONTS.find(x=>x.id===fontId)||MUSHAF_FONTS[0];if(fontId!=='default'&&fontId!=='Amiri Quran'&&fontId!=='Scheherazade New'&&fontId!=='Amiri'){const lid='gf-mushaf-'+fontId.replace(/\s/g,'');if(!$(lid)){const l=document.createElement('link');l.id=lid;l.rel='stylesheet';l.href='https://fonts.googleapis.com/css2?family='+encodeURIComponent(fontId)+'&display=swap';document.head.appendChild(l);}}document.querySelectorAll('#readerContent .m-tx').forEach(el=>{el.style.fontFamily=f.css;el.style.lineHeight=mushafLineHeight;});const v=$('rsFontValue');if(v)v.textContent=f.name;}
function applyMushafFontSize(){const v=$('rsFontSizeValue');if(v)v.textContent=Math.round(fontsize/1.5*100)+'%';document.querySelectorAll('#readerContent .m-tx').forEach(el=>el.style.fontSize=fontsize+'rem');}
function applyMushafLineHeight(){localStorage.setItem('mushafLineHeight',String(mushafLineHeight));const v=$('rsLineHeightValue');if(v)v.textContent=mushafLineHeight.toFixed(2);document.querySelectorAll('#readerContent .m-tx').forEach(el=>el.style.lineHeight=mushafLineHeight);}
function applyMushafTheme(){const viewer=$('readerView');if(!viewer)return;const isDark=mushafTheme==='dark'||(mushafTheme==='auto'&&darkMode);viewer.classList.toggle('mushaf-theme-dark',isDark);const v=$('rsThemeValue');if(v)v.textContent=mushafTheme==='light'?'فاتح':mushafTheme==='dark'?'مظلم':'تلقائي';document.querySelectorAll('#rsThemeSegment button').forEach(b=>b.classList.toggle('active',b.dataset.theme===mushafTheme));}
function applyMushafViewMode(){const wrap=document.querySelector('#readerContent .m-wrap');if(wrap)wrap.classList.toggle('continuous',mushafViewMode==='continuous');const v=$('rsViewModeValue');if(v)v.textContent=mushafViewMode==='pages'?'صفحات مصحف':'مستمر';document.querySelectorAll('#rsViewModeSegment button').forEach(b=>b.classList.toggle('active',b.dataset.mode===mushafViewMode));localStorage.setItem('mushafViewMode',mushafViewMode);}
function applyMushafFocusMode(){const viewer=$('readerView');if(viewer)viewer.classList.toggle('focus-mode',mushafFocusMode);const t=$('rsFocusToggle');if(t)t.classList.toggle('on',mushafFocusMode);localStorage.setItem('mushafFocusMode',String(mushafFocusMode));}
function applyTafsirSource(){localStorage.setItem('tafsirSource',tafsirSource);const info=TAFSIR_SOURCES[tafsirSource]||TAFSIR_SOURCES.mizan;const v=$('rsTafsirValue');if(v)v.textContent=info.name;document.querySelectorAll('#tafsirTabs .tafsir-tab').forEach(t=>t.classList.toggle('active',t.dataset.source===tafsirSource));document.querySelectorAll('#rsTafsirList .rs-item').forEach(it=>it.classList.toggle('selected',it.dataset.source===tafsirSource));}
function showToast(msg,type='default',duration=2000){const t=$('toast');if(!t)return;t.className='toast';if(type&&type!=='default')t.classList.add(type);const clean=msg.replace(/^[✅❌⚠ℹ🗑⏳⏹🔄▶⬇]+\s*/,'');const iconMap={success:'ic-check-circle',error:'ic-times-circle',warning:'ic-exclamation-triangle',info:'ic-info-circle'};const prefix=iconMap[type]?svgIcon(iconMap[type]):'';t.innerHTML='<span>'+prefix+clean+'</span>';t.classList.add('show');clearTimeout(t._timer);if(duration>0)t._timer=setTimeout(()=>t.classList.remove('show'),duration);}
const toast=(m,d)=>showToast(m,'default',d||2000);
const toastSuccess=(m,d)=>showToast(m,'success',d||1800);
const toastError=(m,d)=>showToast(m,'error',d||3000);
const toastWarning=(m,d)=>showToast(m,'warning',d||2500);
const toastInfo=(m,d)=>showToast(m,'info',d||2000);
function showAlertHtml(html,onConfirm){const o=$('customAlert'),m=$('alertMessage');if(!o||!m)return;m.innerHTML=html;o.classList.remove('hidden');o.style.display='flex';document.body.classList.add('no-scroll');const cleanup=()=>{o.classList.add('hidden');o.style.display='';document.body.classList.remove('no-scroll');$('alertConfirm').removeEventListener('click',ch);$('alertCancel').removeEventListener('click',cah);};const ch=()=>{cleanup();if(onConfirm)onConfirm();};const cah=()=>cleanup();$('alertConfirm').addEventListener('click',ch);$('alertCancel').addEventListener('click',cah);}
async function fetchVersionData(){try{const c=new AbortController(),tid=setTimeout(()=>c.abort(),10000);const r=await fetch(UPD_URL,{cache:'no-store',signal:c.signal});clearTimeout(tid);if(!r.ok)return null;const d=await r.json();return d;}catch(e){return null;}}
function hasChangelogData(changelog){if(!changelog)return false;if(Array.isArray(changelog))return changelog.length>0;if(typeof changelog==='object')return Object.keys(changelog).length>0;if(typeof changelog==='string')return changelog.trim().length>0;return false;}
function normalizeChangelog(changelog){if(!changelog)return[];if(Array.isArray(changelog))return changelog;if(typeof changelog==='object')return [changelog];return[];}
async function checkForAppUpdate(){if(!networkOnline)return;const d=await fetchVersionData();if(!d)return;const rv=parseInt(d.version,10);if(!isNaN(rv)&&rv>VER){updateData=d;showUpdateDialog(rv,d.url,d.changelog);}}
function showUpdateDialog(v,url,changelog){const cm=$('updCurrentVer'),nm=$('updNewVer');if(cm)cm.textContent=VER;if(nm)nm.textContent=v;const body=$('updChangelog');if(body){if(hasChangelogData(changelog)){body.innerHTML=renderChangelogHtml(normalizeChangelog(changelog),true);}else{body.innerHTML='<div class="cl-simple-msg">'+svgIcon('ic-download')+'ننصحك بتحديث التطبيق.</div>';}}openModalUniversal('updModal');const btn=$('updNow');if(btn)btn.onclick=()=>{window.open(url||'https://mamhaz.github.io/QuranKarim/QuranKarimv50.apk','_blank');closeModalUniversal('updModal');};const later=$('updLater');if(later)later.onclick=()=>closeModalUniversal('updModal');}
function renderChangelogHtml(changelog,compact){if(!changelog||!changelog.length)return '<div class="cl-empty">لا توجد تحديثات</div>';let h='';changelog.slice(0,compact?1:10).forEach(v=>{h+='<div class="cl-version"><div class="cl-version-header"><span class="cl-badge">v'+escapeHtml(v.version||'')+'</span></div>';if(v.title)h+='<div class="cl-title">'+escapeHtml(v.title)+'</div>';if(v.groups&&v.groups.length){v.groups.forEach(g=>{h+='<div class="cl-group"><div class="cl-group-title">'+escapeHtml(g.name)+'</div>';if(g.items&&g.items.length){h+='<ul class="cl-items">';g.items.forEach(it=>{h+='<li>'+escapeHtml(it)+'</li>';});h+='</ul>';}h+='</div>';});}h+='</div>';});return h;}
function openChangelog(){const body=$('clBody');if(body)body.innerHTML=renderChangelogHtml(CHANGELOG,false);openModalUniversal('clModal');}
function openContactModal(){const m=$('contactModal');if(!m)return;const f=$('contactForm');if(f)f.reset();contactSelectedType='suggestion';updateContactTypeUI();const err=$('ctError');if(err){err.textContent='';err.classList.remove('show');}const dev=$('ctDevice');if(dev)dev.value=(navigator.userAgent||'').slice(0,120);const sub=$('contactSubmit');if(sub){sub.classList.remove('loading');sub.disabled=false;sub.innerHTML=svgIcon('ic-paper-plane')+' إرسال';}openModalUniversal('contactModal');setTimeout(()=>{const n=$('ctName');if(n)n.focus();},350);}
function closeContactModal(){closeModalUniversal('contactModal');}
function showContactError(msg){const err=$('ctError');if(!err)return;err.innerHTML=svgIcon('ic-exclamation-triangle')+' '+msg;err.classList.add('show');}
function selectContactType(val){contactSelectedType=val;updateContactTypeUI();const menu=$('ctTypeMenu'),trigger=$('ctTypeTrigger');if(menu)menu.classList.remove('open');if(trigger)trigger.classList.remove('open');}
function updateContactTypeUI(){const menu=$('ctTypeMenu');if(menu){menu.querySelectorAll('.contact-ms-item').forEach(it=>{it.classList.toggle('selected',it.dataset.value===contactSelectedType);});}const text=$('ctTypeTriggerText');const svgHost=$('ctTypeTriggerEmoji');if(text){const entry=CONTACT_TYPE_LABELS[contactSelectedType];if(entry){if(svgHost)svgHost.innerHTML=svgIcon(entry.icon);text.textContent=entry.label;}}}
function initContactTypeSelect(){const trigger=$('ctTypeTrigger'),menu=$('ctTypeMenu');if(!trigger||!menu)return;trigger.addEventListener('click',function(e){e.stopPropagation();this.classList.toggle('open');menu.classList.toggle('open');});menu.querySelectorAll('.contact-ms-item').forEach(item=>{item.addEventListener('click',function(e){e.stopPropagation();selectContactType(this.dataset.value);});});document.addEventListener('click',function(e){const ms=$('ctTypeMulti');if(ms&&!ms.contains(e.target)){trigger.classList.remove('open');menu.classList.remove('open');}});}
async function submitContactForm(e){e.preventDefault();const f=$('contactForm');const err=$('ctError');const btn=$('contactSubmit');if(!f||!btn)return;const name=$('ctName').value.trim();const email=$('ctEmail').value.trim();const message=$('ctMessage').value.trim();if(!name){showContactError('الرجاء إدخال الاسم');return;}if(!message||message.length<5){showContactError('الرجاء إدخال رسالة (5 أحرف على الأقل)');return;}if(email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){showContactError('البريد الإلكتروني غير صحيح');return;}if(err)err.classList.remove('show');btn.classList.add('loading');btn.disabled=true;btn.innerHTML=svgIcon('ic-sync')+' جاري الإرسال...';try{const entry=CONTACT_TYPE_LABELS[contactSelectedType]||{label:contactSelectedType};const typeLabel=entry.label;const fd=new FormData();fd.append('name',name);if(email)fd.append('email',email);fd.append('type',typeLabel);fd.append('message',message);fd.append('_subject','رسالة '+typeLabel+' — من '+name);fd.append('app_version','5.1');fd.append('user_device',(navigator.userAgent||'').slice(0,120));const r=await fetch(FORMSPREE_URL,{method:'POST',body:fd,headers:{Accept:'application/json'}});if(!r.ok)throw new Error('fail');const box=f.parentElement;box.innerHTML='<div class="form-success">'+svgIcon('ic-check-circle')+'<h4>تم إرسال رسالتك بنجاح</h4><p>شكراً لتواصلك معنا.<br>جزاك الله خيراً</p><button class="btn-close-modal" id="contactDone" style="width:100%;margin-top:1.2rem;">إغلاق</button></div>';const done=$('contactDone');if(done)done.onclick=()=>{closeContactModal();setTimeout(()=>location.reload(),200);};toastSuccess('تم استلام رسالتك');}catch(ex){btn.classList.remove('loading');btn.disabled=false;btn.innerHTML=svgIcon('ic-paper-plane')+' إرسال';showContactError('تعذر الإرسال، تحقق من اتصالك.');}}
window.addEventListener('online',()=>{if(!networkOnline){networkOnline=true;updateNetworkIndicator();toastInfo('تم استعادة الاتصال');}});
window.addEventListener('offline',()=>{if(networkOnline){networkOnline=false;updateNetworkIndicator();toastWarning('تم فقدان الاتصال');}});
function updateNetworkIndicator(){const i=$('networkIndicator'),s=$('networkStatus');if(!i||!s)return;if(networkOnline){i.className='network-indicator online';s.innerHTML=svgIcon('ic-wifi');s.title='متصل';}else{i.className='network-indicator offline';s.innerHTML='<div style="position:relative;display:inline-block;">'+svgIcon('ic-wifi')+'<svg class="ic" style="position:absolute;top:-6px;right:-6px;font-size:0.8rem;color:#e74c3c;background:var(--bg);border-radius:50%;padding:1px;"><use href="#ic-times"/></svg></div>';s.title='غير متصل';}}
$('networkIndicator').addEventListener('click',()=>{if(networkOnline)toastInfo('متصل بالإنترنت');else toastWarning('غير متصل');});
function debouncedSaveState(){if(saveTimeout)clearTimeout(saveTimeout);saveTimeout=setTimeout(()=>{saveState();saveTimeout=null;},500);}
function saveState(){localStorage.setItem('currentReader',currentReader);localStorage.setItem('favSurahs',JSON.stringify(favSurahs));localStorage.setItem('favReaders',JSON.stringify(favReaders));localStorage.setItem('downloadedSurahs',JSON.stringify(downloaded));localStorage.setItem('playSpeed',String(speed));localStorage.setItem('playerVolume',String(volume));localStorage.setItem('quranFontSize',String(fontsize));localStorage.setItem('quranFont',currentFont);localStorage.setItem('darkMode',darkMode?'dark':'light');localStorage.setItem('accentColor',currentColor);localStorage.setItem('playerPinned',String(isPlayerPinned));if(currentSurah>=0&&audio.src&&audio.duration){const t=audio.currentTime||0;if(t<audio.duration)localStorage.setItem('lastPlay',JSON.stringify({reader:currentReader,surah:currentSurah,time:t,timestamp:Date.now()}));}}
function restoreLast(){const l=localStorage.getItem('lastPlay');if(l){try{const d=JSON.parse(l);if(d.reader===currentReader&&d.surah>=0&&d.surah<114){lastSurah=d.surah;lastTime=d.time||0;if(lastTime<0)lastTime=0;}}catch(e){}}}
function saveReadingState(s,a){try{localStorage.setItem('lastReading',JSON.stringify({surah:s,ayah:a,timestamp:Date.now()}));}catch(e){}}
async function isSurahCached(rid,idx){try{const c=await caches.open('quran-audio'),r=await c.match(getReaderUrl(rid,idx));return !!r;}catch(e){return false;}}
let quranTextsLoadingPromise=null;
async function loadQuranTexts(){if(quranTexts&&quranTexts.length===114)return quranTexts;if(quranTextsLoadingPromise)return quranTextsLoadingPromise;quranTextsLoadingPromise=(async()=>{const temp=[];toastInfo('جاري تحميل النص القرآني...');for(let i=1;i<=114;i++){try{const c=new AbortController(),tid=setTimeout(()=>c.abort(),15000);const r=await fetch('https://api.alquran.cloud/v1/surah/'+i+'/quran-simple',{signal:c.signal});clearTimeout(tid);const d=await r.json();if(d?.data?.ayahs){temp.push({surah:i,name:SN[i-1],ayahs:d.data.ayahs.map((a,idx)=>({number:idx+1,text:a.text,normalized:normalizeText(a.text)}))});}}catch(e){}}quranTexts=temp;quranTextsLoadingPromise=null;return quranTexts;})();return quranTextsLoadingPromise;}
async function searchAyahInAllQuran(query){if(!quranTexts||quranTexts.length===0)await loadQuranTexts();if(!query||query.length<2)return[];const results=[],ph=normalizeText(query);if(!ph)return[];let processed=0;for(const surah of quranTexts){for(const ayah of surah.ayahs){const nt=ayah.normalized||normalizeText(ayah.text);if(nt.includes(ph))results.push({surah:surah.surah,surahName:surah.name,ayah:ayah.number,text:ayah.text,score:1});processed++;if(processed%500===0)await new Promise(r=>setTimeout(r,0));}}return results;}
function highlightText(text,query){const terms=normalizeText(query).split(' ').filter(t=>t.length>0);let r=escapeHtml(text);for(const t of terms){const et=t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');r=r.replace(new RegExp(et,'gi'),m=>'<span class="highlight-term">'+m+'</span>');}return r;}
function generateMushafHtml(ayahs,surahNum,surahName,targetAyah){const pages={},order=[];ayahs.forEach(a=>{const p=a.page||1;if(!pages[p]){pages[p]=[];order.push(p);}pages[p].push(a);});order.sort((a,b)=>a-b);const f=MUSHAF_FONTS.find(x=>x.id===mushafFont)||MUSHAF_FONTS[0];let html='<div class="m-wrap'+(mushafViewMode==='continuous'?' continuous':'')+'">';order.forEach((p,pi)=>{html+='<div class="m-page"><div class="m-frame">';if(pi===0){html+='<div class="m-band"><span>سورة '+surahName+'</span></div>';if(surahNum!==1&&surahNum!==9){html+='<div class="m-bs">بِسْمِ ٱللَّهِ ٱلرَّحْمَٰنِ ٱلرَّحِيمِ</div>';}}html+='<div class="m-tx" style="font-size:'+fontsize+'rem;font-family:'+f.css+';line-height:'+mushafLineHeight+'">';pages[p].forEach(a=>{let txt=a.text;if(pi===0&&a.numberInSurah===1&&surahNum!==1&&surahNum!==9){const marker='ٱلرَّحِيمِ';const i=txt.indexOf(marker);if(i!==-1)txt=txt.substring(i+marker.length).trim();}const tgt=targetAyah&&+targetAyah===a.numberInSurah;html+='<span class="ayah-line'+(tgt?' hl':'')+'" data-s="'+surahNum+'" data-a="'+a.numberInSurah+'" data-text="'+escapeHtml(txt)+'">'+txt+'<span class="an">'+arNum(a.numberInSurah)+'</span></span> ';});html+='</div>';html+='<div class="m-num"><span class="num-orn">۞</span>'+arNum(p)+'<span class="num-orn">۞</span></div>';html+='</div></div>';});html+='</div>';return html;}
async function getTafsirFromFile(surah,ayah){const CSZ=50,BASE='https://raw.githubusercontent.com/MAmhaz/QuranKarim/main/Data2/';const isLong=(AYAH_COUNTS[surah]||0)>CSZ;let url='';if(isLong){const p=Math.ceil(ayah/CSZ);url=BASE+'tafsir_'+surah+'_part'+p+'.json';}else url=BASE+'tafsir_'+surah+'.json';try{const r=await fetch(url);if(!r.ok)throw new Error('fail');const data=await r.json();const ad=data[ayah];if(!ad)return{text:'الآية غير موجودة في هذا التفسير',mufassir:'تفسير الميزان'};return{text:ad['layer1_ar']||'التفسير غير متوفر',mufassir:'تفسير الميزان (العلامة الطباطبائي)'};}catch(e){return{text:'حدث خطأ في تحميل التفسير',mufassir:'تفسير الميزان'};}}
async function getTafsirFromApi(surah,ayah,code){try{const c=new AbortController(),tid=setTimeout(()=>c.abort(),8000);const r=await fetch('https://api.alquran.cloud/v1/ayah/'+surah+':'+ayah+'/'+code,{signal:c.signal});clearTimeout(tid);if(!r.ok)throw new Error('fail');const d=await r.json();return d?.data?.text||'التفسير غير متوفر';}catch(e){return null;}}
async function fetchTafsir(surah,ayah,source){const info=TAFSIR_SOURCES[source]||TAFSIR_SOURCES.mizan;if(info.type==='file'){return await getTafsirFromFile(surah,ayah);}const txt=await getTafsirFromApi(surah,ayah,info.code);if(txt===null)return{text:'تعذر تحميل التفسير، تحقق من اتصالك',mufassir:info.name+' — '+info.author};return{text:txt,mufassir:info.name+' — '+info.author};}
async function renderAllSurahs(force=false){if(isRendering)return;if(!force&&!isInitialRender&&document.querySelector('.surah-card'))return;isRendering=true;isInitialRender=false;try{const grid=$('surahGrid');if(!grid){isRendering=false;return;}grid.innerHTML='';const rid=currentReader;if(!surahAvailability[rid])surahAvailability[rid]={};for(let i=0;i<TOTAL;i++){const isInCache=await isSurahCached(rid,i);const card=document.createElement('div');card.className='surah-card';card.dataset.idx=i;const isFav=favSurahs.indexOf(i)!==-1;const isPartial=downloadProgress[rid]&&downloadProgress[rid][i]!==undefined&&downloadProgress[rid][i]<100;let btnHtml='';if(isPartial){const pct=Math.round(downloadProgress[rid][i]);btnHtml='<button class="download-btn downloading" data-idx="'+i+'" data-action="resume"><svg class="progress-ring" viewBox="0 0 40 40"><circle class="bg" cx="20" cy="20" r="16"/><circle class="fg" cx="20" cy="20" r="16" stroke-dasharray="100.53" stroke-dashoffset="'+(100.53*(1-pct/100))+'"/></svg><span class="progress-text">'+pct+'%</span><span class="cancel-icon" data-idx="'+i+'">×</span></button>';}else if(isInCache){btnHtml='<button class="download-btn downloaded" data-idx="'+i+'" title="حذف التنزيل">'+svgIcon('ic-check-circle')+'</button>';}else{btnHtml='<button class="download-btn" data-idx="'+i+'">'+svgIcon('ic-download')+'</button>';}card.innerHTML='<div class="surah-main-row"><span class="surah-number">'+(i+1)+'</span><span class="surah-name">'+SN[i]+'</span><div class="surah-actions"><button class="play-btn" data-idx="'+i+'">'+svgIcon('ic-play')+'</button><button class="read-btn" data-idx="'+i+'">'+svgIcon('ic-book-open')+'</button><button class="fav-btn '+(isFav?'active':'')+'" data-idx="'+i+'">'+svgIcon(isFav?'ic-star-fill':'ic-star')+'</button>'+btnHtml+'</div></div>';grid.appendChild(card);}grid.addEventListener('click',handleSurahAction);}catch(e){}finally{isRendering=false;}}
function handleSurahAction(e){const t=e.target.closest('button');if(!t)return;const card=t.closest('.surah-card');if(!card)return;const idx=parseInt(card.dataset.idx);if(isNaN(idx))return;e.stopPropagation();if(t.classList.contains('play-btn'))playSurah(idx,0);else if(t.classList.contains('read-btn'))openReader(idx);else if(t.classList.contains('fav-btn'))toggleFavSurah(idx);else if(t.classList.contains('download-btn')){const isDl=downloaded[currentReader]?.[idx]?.downloaded;if(isDl){showDeleteConfirm(idx);return;}if(idx<0||idx>113){toastError('رقم سورة غير صحيح');return;}const did=currentReader+'_'+idx;if(activeDownloads[did]){showAlertHtml(svgIcon('ic-hourglass')+' التحميل جارٍ بالفعل لسورة <strong>"'+SN[idx]+'"</strong>.<br>هل تريد إلغاء التحميل؟',()=>{const di=activeDownloads[did];if(di?.xhr)di.xhr.abort();toastInfo('تم إلغاء تحميل "'+SN[idx]+'"');if(downloadProgress[currentReader])delete downloadProgress[currentReader][idx];renderAllSurahs(true);});return;}showDownloadConfirm(idx);}}
function filterSurahs(filter){currentFilter=filter;const cards=document.querySelectorAll('.surah-card'),rid=currentReader;let count=0;document.querySelectorAll('.filter-option').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));cards.forEach(card=>{const idx=parseInt(card.dataset.idx),isDl=downloaded[rid]?.[idx]?.downloaded;let show=true;switch(filter){case 'available':case 'unavailable':show=false;break;case 'downloaded':show=isDl;break;case 'notdownloaded':show=!isDl;break;}card.style.display=show?'flex':'none';if(show)count++;});const grid=$('surahGrid'),noResult=$('noFilterResult'),fname=getFilterName(filter);if(count===0&&filter!=='all'&&grid){if(!noResult){const n=document.createElement('div');n.id='noFilterResult';n.className='no-surah-result';grid.appendChild(n);}const nr=$('noFilterResult');nr.innerHTML=svgIcon('ic-search')+' لا توجد سور بفلتر "<strong style="color:var(--gold-dark);">'+fname+'</strong>"';nr.style.display='block';}else if(noResult)noResult.remove();}
