function hasFilterResults(filter){const rid=currentReader;let count=0;document.querySelectorAll('.surah-card').forEach(card=>{const idx=parseInt(card.dataset.idx),isDl=downloaded[rid]?.[idx]?.downloaded;let show=true;switch(filter){case 'available':case 'unavailable':show=false;break;case 'downloaded':show=isDl;break;case 'notdownloaded':show=!isDl;break;}if(show)count++;});return count>0;}
