function resetPlayer(keepExpanded){audio.pause();audio.src='';audio.playbackRate=speed;stopSessionSaver();isPlaying=false;currentSurah=-1;updatePlayerUI();const f=$('playerProgressFill'),c=$('playerTimeCur'),d=$('playerTimeDur'),i=$('playerInfo'),p=$('bottomPlayer');if(f)f.style.width='0%';if(c)c.textContent='00:00';if(d)d.textContent='00:00';if(i)i.textContent='';if(p&&!keepExpanded){p.classList.remove('visible');p.style.bottom='0px';document.body.style.paddingBottom='5rem';}updatePlayerFavButton();updatePlayerTitle();}
function playSurah(idx,startTime){startTime=startTime||0;const rid=currentReader;if(idx<0||idx>113){toastError('رقم سورة غير صحيح');return;}const url=getReaderUrl(rid,idx);if(!url){toastError('تعذر الحصول على الرابط');return;}if(currentSurah===idx&&audio.src&&!audio.paused){audio.pause();isPlaying=false;updatePlayerUI();return;}if(currentSurah===idx&&audio.src&&audio.paused){audio.play();isPlaying=true;updatePlayerUI();return;}if(isRadio)stopRadio();audio.src=url;currentSurah=idx;audio.volume=volume;audio.load();if(downloaded[currentReader]?.[idx]){downloaded[currentReader][idx].lastPlayedAt=new Date().toISOString();debouncedSaveState();}audio.currentTime=startTime;const p=$('bottomPlayer');if(p){p.classList.add('visible');updateFooterHeight();}audio.play().then(()=>{isPlaying=true;updatePlayerUI();toastSuccess('تشغيل "'+SN[idx]+'"');startSessionSaver();updatePlayerFavButton();updatePlayerTitle();const b=$('randomAyahBanner');if(b)b.classList.remove('visible');updateBannerToggleBtn();}).catch(()=>{toastError('فشل التشغيل، تأكد من الاتصال');});}
function startRadio(){const url=getRadioUrl(currentReader);if(!url){toastWarning('لا يوجد راديو لهذا القارئ');return;}if(isRadio){stopRadio();return;}audio.pause();audio.src='';isPlaying=false;currentSurah=-1;updatePlayerUI();radioAudio.src=url;radioAudio.volume=volume;let a=0;const tryRadio=()=>{const p=radioAudio.play();if(p!==undefined){p.then(()=>{isRadio=true;isRadioPlaying=true;toastSuccess('تم تشغيل راديو '+getReaderName(currentReader));renderReaderList();updateRadioBtnUI();}).catch(()=>{a++;if(a<3){setTimeout(tryRadio,2000);}else toastError('تعذر تشغيل الراديو');});}};tryRadio();}
