audio.addEventListener('timeupdate',()=>{if(audio.duration&&!isRadio){const p=(audio.currentTime/audio.duration)*100,f=$('playerProgressFill'),c=$('playerTimeCur'),d=$('playerTimeDur');if(f)f.style.width=p+'%';if(c)c.textContent=formatTime(audio.currentTime);if(d)d.textContent=formatTime(audio.duration);if(isPlayerPinned&&isReaderOpen){const pf=$('miniProgressFill'),mc=$('miniTimeCur'),md=$('miniTimeDur');if(pf)pf.style.width=p+'%';if(mc)mc.textContent=formatTime(audio.currentTime);if(md)md.textContent=formatTime(audio.duration);}}if(!isPageHidden&&currentTiming&&isReaderOpen&&currentReadingSurah===currentSurah&&currentTiming.verse_timings){const now=Date.now();if(now-lastSyncHighlightTime<800)return;lastSyncHighlightTime=now;const t=audio.currentTime*1000;let curAyah=null;for(let i=0;i<currentTiming.verse_timings.length;i++){const v=currentTiming.verse_timings[i];if(t>=v.timestamp_from)curAyah=v;else break;}if(curAyah){const ayahNum=parseInt(curAyah.verse_key.split(':')[1],10);if(ayahNum!==lastSyncedAyah){lastSyncedAyah=ayahNum;highlightAndScrollToAyah(ayahNum,false);}}}});
audio.addEventListener('ended',()=>{if(repeatMode==='one'){audio.currentTime=0;audio.play();return;}if(repeatMode==='all'){const vs=[];document.querySelectorAll('.surah-card').forEach(c=>{if(c.style.display!=='none'){const i=parseInt(c.dataset.idx);if(!isNaN(i))vs.push(i);}});if(vs.length===0){isPlaying=false;updatePlayerUI();return;}const ci=vs.indexOf(currentSurah),ni=(ci+1)%vs.length;toastInfo('السورة '+SN[vs[ni]]);playSurah(vs[ni],0);return;}isPlaying=false;updatePlayerUI();});
