function getSessions(){try{return JSON.parse(localStorage.getItem('sessions')||'[]');}catch(e){return[];}}
function saveSessions(s){localStorage.setItem('sessions',JSON.stringify(s));}
function addSession(type,reader,surah,time){let s=getSessions();if(type==='surah'||type==='reader'){s=s.filter(x=>x.type!==type);}else{const i=s.findIndex(x=>x.type===type&&x.reader===reader&&x.surah===surah);if(i!==-1)s.splice(i,1);}s.push({type,reader:reader||currentReader,surah:surah!==undefined?surah:-1,time:time||(audio.currentTime||0),timestamp:Date.now()});saveSessions(s);}
function removeSession(i){const s=getSessions();s.splice(i,1);saveSessions(s);}
function startSessionSaver(){if(sessionSaveInterval)clearInterval(sessionSaveInterval);sessionSaveInterval=setInterval(()=>{if(currentSurah>=0&&isPlaying&&audio.src&&!audio.paused&&audio.currentTime>0)addSession('surah',currentReader,currentSurah,audio.currentTime);},15000);}
function stopSessionSaver(){if(sessionSaveInterval){clearInterval(sessionSaveInterval);sessionSaveInterval=null;}}
function checkLastSession(){const sessions=getSessions();if(sessions.length===0)return;const now=Date.now();const valid=sessions.filter(s=>(now-s.timestamp)/(1000*60*60)<=48);if(valid.length===0)return;if(document.querySelector('.resume-overlay'))return;let html='';valid.forEach((s,index)=>{const rn=getReaderName(s.reader),ts=formatTime(s.time||0);if(s.type==='surah'){const sn=SN[s.surah]||'غير معروف';html+='<div class="resume-item"><div class="resume-item-title">'+svgIcon('ic-headphones')+' استماع: سورة '+sn+' ('+rn+')</div><div><button class="resume-btn" data-index="'+index+'" data-action="play" data-reader="'+s.reader+'" data-surah="'+s.surah+'" data-time="'+s.time+'">'+svgIcon('ic-play')+' متابعة ('+ts+')</button><button class="resume-btn" data-index="'+index+'" data-action="play" data-reader="'+s.reader+'" data-surah="'+s.surah+'" data-time="0">'+svgIcon('ic-redo')+' إعادة</button><button class="resume-ignore-btn" data-index="'+index+'">'+svgIcon('ic-stop-circle')+' تجاهل</button></div></div>';}else if(s.type==='reader'){const sn=SN[s.surah]||'غير معروف';html+='<div class="resume-item"><div class="resume-item-title">'+svgIcon('ic-book-open')+' قراءة: سورة '+sn+'</div><div><button class="resume-btn" data-index="'+index+'" data-action="read" data-surah="'+s.surah+'">'+svgIcon('ic-book-open')+' فتح</button><button class="resume-ignore-btn" data-index="'+index+'">'+svgIcon('ic-stop-circle')+' تجاهل</button></div></div>';}});if(!html)return;const overlay=document.createElement('div');overlay.className='resume-overlay';overlay.innerHTML='<div><h3 class="resume-title">'+svgIcon('ic-history')+' استئناف الجلسات السابقة</h3><div style="margin:1rem 0;">'+html+'</div><button class="btn-close-modal" id="sessionClose" style="width:100%;">إغلاق</button></div>';document.body.appendChild(overlay);document.body.style.overflow='hidden';overlay.querySelectorAll('.resume-btn').forEach(b=>{b.addEventListener('click',function(){const action=this.dataset.action,index=parseInt(this.dataset.index),rid=this.dataset.reader,surah=parseInt(this.dataset.surah),time=parseFloat(this.dataset.time)||0;if(action==='play'&&rid){selectReader(rid);setTimeout(()=>{if(rid===currentReader&&surah===currentSurah)currentSurah=-1;playSurah(surah,time);},300);removeSession(index);}else if(action==='read'){openReader(surah);removeSession(index);}const item=this.closest('.resume-item');if(item)item.remove();if(overlay.querySelectorAll('.resume-item').length===0){overlay.remove();document.body.style.overflow='';}});});overlay.querySelectorAll('.resume-ignore-btn').forEach(b=>{b.addEventListener('click',function(){const index=parseInt(this.dataset.index);removeSession(index);const item=this.closest('.resume-item');if(item)item.remove();if(overlay.querySelectorAll('.resume-item').length===0){overlay.remove();document.body.style.overflow='';}});});overlay.querySelector('#sessionClose').addEventListener('click',()=>{overlay.remove();document.body.style.overflow='';});}
function openReader(idx){if(idx<0||idx>113){toastError('رقم سورة غير صحيح');return;}const view=$('readerView'),title=$('readerTitle');if(!view||!title)return;currentReadingSurah=idx;const b=$('randomAyahBanner');if(b)b.classList.remove('visible');updateBannerToggleBtn();view.classList.add('visible');title.innerHTML=SN[idx]+' <span style="font-size:calc(0.65rem*var(--text-scale));opacity:0.6;color:var(--text-secondary);">('+ST[idx]+')</span>';applyMushafTheme();applyMushafFocusMode();loadSurahTextMushaf(idx,null);isReaderOpen=true;addSession('reader',currentReader,idx,0);pushWindow('readerView');history.pushState({modal:'readerView',level:windowStack.length},'');history.pushState({modal:'readerView',level:windowStack.length},'');$('readerSearchContainer').style.display='none';$('readerSearchInput').value='';$('readerSearchCount').textContent='0/0';clearSearchHighlights();updateReaderNavButtons();updateSyncIndicator();updateMiniPlayer();}
function openReaderWithAyah(idx,targetAyah){if(idx<0||idx>113){toastError('رقم سورة غير صحيح');return;}const view=$('readerView'),title=$('readerTitle');if(!view||!title)return;currentReadingSurah=idx;const b=$('randomAyahBanner');if(b)b.classList.remove('visible');updateBannerToggleBtn();view.classList.add('visible');title.innerHTML=SN[idx]+' <span style="font-size:calc(0.65rem*var(--text-scale));opacity:0.6;color:var(--text-secondary);">('+ST[idx]+')</span>';applyMushafTheme();applyMushafFocusMode();loadSurahTextMushaf(idx,targetAyah);isReaderOpen=true;addSession('reader',currentReader,idx,0);pushWindow('readerView');history.pushState({modal:'readerView',level:windowStack.length},'');history.pushState({modal:'readerView',level:windowStack.length},'');$('readerSearchContainer').style.display='none';$('readerSearchInput').value='';$('readerSearchCount').textContent='0/0';clearSearchHighlights();updateReaderNavButtons();updateSyncIndicator();updateMiniPlayer();}
function closeReader(){const v=$('readerView');if(v)v.classList.remove('visible');isReaderOpen=false;const sessions=getSessions(),i=sessions.findIndex(s=>s.type==='reader'&&s.reader===currentReader&&s.surah===currentReadingSurah);if(i!==-1)removeSession(i);currentReadingSurah=-1;currentTiming=null;lastSyncedAyah=-1;windowStack=windowStack.filter(w=>w!=='readerView');$('readerSearchContainer').style.display='none';$('readerSearchInput').value='';$('readerSearchCount').textContent='0/0';clearSearchHighlights();updateSyncIndicator();const mp=$('miniPlayer');if(mp)mp.classList.remove('visible');const rv=$('readerView');if(rv)rv.classList.remove('with-mini-player');const rc=$('readerContent');if(rc)rc.innerHTML='';}
function updateReaderNavButtons(){const p=$('readerPrevBtn'),n=$('readerNextBtn');if(!p||!n)return;p.classList.add('nav-btn');n.classList.add('nav-btn');p.classList.toggle('disabled',currentReadingSurah<=0);n.classList.toggle('disabled',currentReadingSurah>=113);}
function navigateReader(direction){if(currentReadingSurah<0){toastWarning('لم يتم فتح أي سورة');return;}const newIdx=currentReadingSurah+direction;if(newIdx<0){toastWarning('أنت في أول سورة');return;}if(newIdx>113){toastWarning('أنت في آخر سورة');return;}openReader(newIdx);setTimeout(()=>{updateReaderNavButtons();const v=$('readerView');if(v)v.scrollTop=0;},100);toastInfo('سورة '+SN[newIdx]+' ('+(newIdx+1)+')');}
function syncReaderWithPlayer(newIdx){if(!isReaderOpen){return;}if(newIdx<0||newIdx>113){return;}const view=$('readerView'),title=$('readerTitle');if(!view||!title)return;currentReadingSurah=newIdx;title.innerHTML=SN[newIdx]+' <span style="font-size:calc(0.65rem*var(--text-scale));opacity:0.6;color:var(--text-secondary);">('+ST[newIdx]+')</span>';currentTiming=null;lastSyncedAyah=-1;updateSyncIndicator();loadSurahTextMushaf(newIdx,null);updateReaderNavButtons();const b=$('readerSearchContainer');if(b)b.style.display='none';clearSearchHighlights();}
async function loadSurahTextMushaf(idx,targetAyah){const c=$('readerContent');if(!c)return;currentTiming=null;lastSyncedAyah=-1;updateSyncIndicator();if(SYNC_READERS[currentReader]){loadTimingData(currentReader,idx).then(t=>{currentTiming=t;updateSyncIndicator();});}c.innerHTML='<div class="m-load"><div class="loading-spinner"></div><br>جاري تحميل السورة...</div>';try{const r=await fetch('https://api.alquran.cloud/v1/surah/'+(idx+1)+'/quran-uthmani');const d=await r.json();if(!d?.data?.ayahs)throw new Error('no data');const h=generateMushafHtml(d.data.ayahs,idx+1,SN[idx],targetAyah);c.innerHTML=h;bindAyahClicks(c);applyMushafViewMode();if(targetAyah){setTimeout(()=>{scrollAyahToCenter(targetAyah,true);},350);}}catch(e){c.innerHTML='<div class="m-load">'+svgIcon('ic-exclamation-triangle')+'<br>فشل تحميل السورة<br><span style="font-size:calc(.8rem*var(--text-scale));color:var(--text-secondary);">تحقق من الاتصال بالإنترنت</span></div>';}}
function bindAyahClicks(c){c.querySelectorAll('.ayah-line').forEach(el=>{el.onclick=e=>{e.stopPropagation();const sn=+el.dataset.s,an=+el.dataset.a,txt=el.dataset.text||el.textContent.replace(/[٠-٩0-9]+/g,'').trim();currentAyahText=txt;showTafsir(sn,an);};});}
function adjFontSize(delta){fontsize=Math.round(Math.min(3.4,Math.max(1,fontsize+delta))*100)/100;localStorage.setItem('quranFontSize',String(fontsize));applyMushafFontSize();}
let readerSearchResults=[],readerSearchIndex=-1;
function clearSearchHighlights(){document.querySelectorAll('.ayah-line').forEach(el=>el.classList.remove('search-highlight','search-current'));}
function searchInCurrentSurah(q){const c=$('readerContent');if(!c)return;const ayahs=c.querySelectorAll('.ayah-line');clearSearchHighlights();readerSearchResults=[];readerSearchIndex=-1;if(!q||q.length<2){$('readerSearchCount').textContent='0/0';return;}const nq=normalizeText(q),terms=nq.split(' ').filter(t=>t.length>0),exact=terms.length>1;ayahs.forEach((ayah,i)=>{const text=ayah.dataset.text||ayah.textContent,nt=normalizeText(text);let m=false;if(exact){m=terms.every(t=>nt.includes(t));}else m=nt.includes(terms[0]);if(m){readerSearchResults.push(i);ayah.classList.add('search-highlight');}});if(readerSearchResults.length>0){readerSearchIndex=0;highlightReaderResult(readerSearchResults[0]);$('readerSearchCount').textContent='1/'+readerSearchResults.length;}else $('readerSearchCount').textContent='0/0';}
function highlightReaderResult(i){const ayahs=$('readerContent').querySelectorAll('.ayah-line');ayahs.forEach(el=>el.classList.remove('search-current'));if(i>=0&&i<ayahs.length){const a=ayahs[i];a.classList.add('search-current');a.scrollIntoView({behavior:'auto',block:'center'});}}
async function renderTafsirContent(){const te=$('tafsirText'),t=$('tafsirTitle');if(!te||!t)return;t.textContent='تفسير الآية '+currentTafsirAyah+' من سورة '+SN[currentTafsirSurah-1];te.innerHTML='<div style="text-align:center;padding:2rem 0;"><div class="loading-spinner"></div><br>'+svgIcon('ic-hourglass')+' جاري تحميل التفسير...</div>';const res=await fetchTafsir(currentTafsirSurah,currentTafsirAyah,tafsirSource);const at=currentTafsirAyahText||'الآية غير متوفرة';te.innerHTML='<div style="margin-bottom:10px;padding:6px 10px;background:rgba(var(--gold-rgb),0.08);border-right:3px solid var(--gold);border-radius:6px;"><strong style="color:var(--gold-dark);font-size:calc(0.9rem*var(--text-scale));">'+svgIcon('ic-book-open')+' الآية:</strong><br><span style="color:var(--text);font-size:calc(0.95rem*var(--text-scale));line-height:1.7;font-family:\'Amiri Quran\',serif;">'+escapeHtml(at)+'</span></div><div style="margin-bottom:10px;padding:6px 10px;background:rgba(var(--gold-rgb),0.08);border-right:3px solid var(--gold);border-radius:6px;"><strong style="color:var(--gold-dark);font-size:calc(0.9rem*var(--text-scale));">'+svgIcon('ic-book')+' المفسر:</strong> <span style="color:var(--text);">'+escapeHtml(res.mufassir)+'</span></div><div style="color:var(--text);font-size:calc(0.95rem*var(--text-scale));line-height:1.9;">'+res.text+'</div>';const sb=$('tafsirShareBtn');if(sb)sb.onclick=()=>{const st='الآية: '+at+'\n— سورة '+SN[currentTafsirSurah-1]+' (الآية '+currentTafsirAyah+') —\n\nالمفسر: '+res.mufassir+'\nالتفسير: '+res.text+'\n\nتطبيق القرآن الكريم\nمنجد أمهز\nhttps://mamhaz.github.io/QuranKarim';if(navigator.share){try{navigator.share({title:'الآية '+currentTafsirAyah,text:st});}catch(e){}}else{try{navigator.clipboard.writeText(st);toastSuccess('تم نسخ التفسير');}catch(e){toastError('تعذر المشاركة');}}};saveReadingState(currentTafsirSurah,currentTafsirAyah);}
function updateCurrentAyahText(){const surahData=quranTexts?.find(s=>s.surah===currentTafsirSurah);if(surahData&&surahData.ayahs[currentTafsirAyah-1]){currentTafsirAyahText=surahData.ayahs[currentTafsirAyah-1].text;}else{currentTafsirAyahText='';}}
function updateTafsirNavButtons(){const p=$('tafsirPrevBtn'),n=$('tafsirNextBtn');if(!p||!n)return;const maxA=AYAH_COUNTS[currentTafsirSurah]||0;p.classList.toggle('disabled',currentTafsirAyah<=1);n.classList.toggle('disabled',currentTafsirAyah>=maxA);}
function navigateTafsirAyah(direction){if(!currentTafsirSurah)return;const maxA=AYAH_COUNTS[currentTafsirSurah]||0;const newAyah=currentTafsirAyah+direction;if(newAyah<1){toastWarning('هذه أول آية في السورة');return;}if(newAyah>maxA){toastWarning('هذه آخر آية في السورة');return;}currentTafsirAyah=newAyah;updateCurrentAyahText();renderTafsirContent();updateTafsirNavButtons();const tt=$('tafsirText');if(tt)tt.scrollTop=0;}
async function showTafsir(surah,ayah){const m=$('tafsirModal');if(!m)return;currentTafsirSurah=surah;currentTafsirAyah=ayah;currentTafsirAyahText=currentAyahText;openModalUniversal('tafsirModal');document.querySelectorAll('#tafsirTabs .tafsir-tab').forEach(t=>t.classList.toggle('active',t.dataset.source===tafsirSource));updateTafsirNavButtons();renderTafsirContent();}
function showSearchLoading(){const c=$('readerSearchResults');if(!c)return;c.innerHTML='<div class="search-loading-indicator"><div class="search-spinner"></div><div class="search-loading-text">'+svgIcon('ic-search')+' جاري البحث في القرآن الكريم...</div></div>';c.classList.add('show');}
function renderAyahSearchResults(results,query){const c=$('readerSearchResults');c.innerHTML='';c.classList.add('show');if(results.length===0){c.innerHTML='<div class="reader-search-item ayah-no-result-msg">'+svgIcon('ic-search')+' لا توجد آيات تطابق "<strong>'+escapeHtml(query)+'</strong>"</div>';return;}let h='';results.forEach(r=>{h+='<div class="reader-search-item ayah-result-item" data-surah="'+r.surah+'" data-ayah="'+r.ayah+'"><div class="ayah-result-content"><span class="ayah-text">'+highlightText(r.text,query)+'</span><div class="ayah-meta"><span class="ayah-location">'+svgIcon('ic-book-open')+' '+escapeHtml(r.surahName)+' (الآية '+r.ayah+')</span></div></div></div>';});c.innerHTML='<div class="ayah-results-header"><span class="results-title">'+svgIcon('ic-book')+' نتائج البحث: '+results.length+'</span><button class="close-results-btn" id="closeAyahResults">'+svgIcon('ic-times')+'</button></div>'+h;c.querySelector('#closeAyahResults').addEventListener('click',()=>{c.classList.remove('show');$('searchMainInput').value='';$('searchClearBtn').classList.remove('visible');$('searchResultsInfo').classList.remove('show');});c.querySelectorAll('.ayah-result-item').forEach(item=>{item.addEventListener('click',function(){const s=parseInt(this.dataset.surah),a=parseInt(this.dataset.ayah);c.classList.remove('show');$('searchMainInput').value='';$('searchClearBtn').classList.remove('visible');$('searchResultsInfo').classList.remove('show');openReaderWithAyah(s-1,a);});});}
function updateSearchResultsInfo(filter){const info=$('searchResultsInfo');if(!info)return;const q=(filter||'').trim();if(!q){info.classList.remove('show');return;}if(searchTarget==='readers'){let c=R.filter(r=>r.name.indexOf(q.toLowerCase())!==-1);if(readersWithRadioOnly)c=c.filter(r=>r.radio&&r.radio.length>0);info.textContent='تم العثور على '+c.length+' قارئ';info.classList.add('show');}else if(searchTarget==='surahs'){const parts=q.split(' ');const c=SN.filter(n=>parts.every(p=>n.indexOf(p)!==-1)).length;info.textContent='تم العثور على '+c+' سورة';info.classList.add('show');}else if(searchTarget==='ayahs'){info.textContent='ابحث عن آية (حرفين على الأقل)';info.classList.add('show');}}
function updateReaderSearchResults(filter){const c=$('readerSearchResults');if(!c)return;const q=(filter||'').trim().toLowerCase();if(!q||searchTarget!=='readers'){c.classList.remove('show');return;}let f=R.filter(e=>e.name.indexOf(q)!==-1);if(readersWithRadioOnly){f=f.filter(e=>e.radio&&e.radio.length>0);}if(f.length===0){c.innerHTML='<div class="reader-search-item reader-no-result-msg">'+svgIcon('ic-search')+' لا توجد نتائج</div>';}else{c.innerHTML=f.map(e=>'<div class="reader-search-item" data-reader="'+e.id+'">'+e.name+'</div>').join('');c.querySelectorAll('.reader-search-item[data-reader]').forEach(item=>{item.addEventListener('click',()=>{selectReader(item.dataset.reader);$('searchMainInput').value='';c.classList.remove('show');$('searchResultsInfo').classList.remove('show');$('searchClearBtn').classList.remove('visible');});});}c.classList.add('show');}
function searchSurahs(query){const grid=$('surahGrid');if(!grid)return;if(grid.children.length===0){renderAllSurahs(true);requestAnimationFrame(()=>searchSurahs(query));return;}const t=query.trim().toLowerCase(),cards=grid.querySelectorAll('.surah-card');if(!t){cards.forEach(c=>c.style.display='flex');const n=$('noSurahResult');if(n)n.remove();return;}const parts=t.split(' ').filter(p=>p.length>0);let found=false,matched=[];cards.forEach(c=>{const name=c.querySelector('.surah-name').textContent.toLowerCase();const m=parts.every(p=>name.includes(p));c.style.display=m?'flex':'none';if(m){found=true;matched.push(c);}});let n=$('noSurahResult');if(!found){if(!n){n=document.createElement('div');n.id='noSurahResult';n.className='no-surah-result';grid.appendChild(n);}n.innerHTML=svgIcon('ic-search')+' لا توجد سور تطابق بحثك';n.style.display='block';}else if(n)n.remove();if(matched.length===1){matched[0].scrollIntoView({behavior:'auto',block:'center'});matched[0].style.background='rgba(201,168,76,0.15)';setTimeout(()=>matched[0].style.background='',2000);}}
function showFavReadersModal(){const fl=R.filter(r=>favReaders.indexOf(r.id)!==-1);if(fl.length===0){toastInfo('لا يوجد قراء مفضلون');return;}const o=document.createElement('div');o.className='tafsir-modal show';o.style.display='flex';o.innerHTML='<div class="tafsir-content"><h3>'+svgIcon('ic-star')+' مفضلة القراء</h3><div class="modal-list">'+fl.map(r=>'<div class="modal-item" data-id="'+r.id+'"><span class="item-name">'+r.name+'</span><span class="item-action">'+svgIcon('ic-chevron-left')+'</span></div>').join('')+'</div><button class="btn-close-modal" id="favReadersClose">'+svgIcon('ic-times')+' إغلاق</button></div>';document.body.appendChild(o);document.body.style.overflow='hidden';const close=()=>{o.remove();document.body.style.overflow='';windowStack=windowStack.filter(w=>w!=='favReadersModal');};o.querySelectorAll('.modal-item').forEach(i=>i.addEventListener('click',()=>{selectReader(i.dataset.id);close();}));o.querySelector('#favReadersClose').addEventListener('click',close);o.addEventListener('click',e=>{if(e.target===e.currentTarget)close();});}
function showFavSurahsModal(){if(favSurahs.length===0){toastInfo('لا توجد سور مفضلة');return;}const o=document.createElement('div');o.className='tafsir-modal show';o.style.display='flex';o.innerHTML='<div class="tafsir-content"><h3>'+svgIcon('ic-bookmark')+' مفضلة السور</h3><div class="modal-list">'+favSurahs.map(i=>'<div class="modal-item" data-idx="'+i+'"><span class="item-name">'+SN[i]+'</span><span class="item-action">'+svgIcon('ic-play')+'</span></div>').join('')+'</div><button class="btn-close-modal" id="favSurahsClose">'+svgIcon('ic-times')+' إغلاق</button></div>';document.body.appendChild(o);document.body.style.overflow='hidden';const close=()=>{o.remove();document.body.style.overflow='';windowStack=windowStack.filter(w=>w!=='favSurahsModal');};o.querySelectorAll('.modal-item').forEach(i=>i.addEventListener('click',()=>{const idx=parseInt(i.dataset.idx);close();playSurah(idx,0);}));o.querySelector('#favSurahsClose').addEventListener('click',close);o.addEventListener('click',e=>{if(e.target===e.currentTarget)close();});}
function showDownloadConfirm(idx){if(idx<0||idx>113){toastError('رقم سورة غير صحيح');return;}confirmIdx=idx;const rid=currentReader,rn=getReaderName(rid),sn=SN[idx]||'سورة '+(idx+1);$('dlConfirmSurah').textContent=sn;$('dlConfirmReader').textContent='القارئ: '+rn;const se=$('dlConfirmSize');se.textContent='جاري حساب الحجم...';se.style.color='var(--text-secondary)';getFileSize(getReaderUrl(rid,idx)).then(size=>{const st=size>0?formatSize(size):'غير معروف';se.innerHTML=svgIcon('ic-box')+' الحجم: <strong>'+st+'</strong>';se.style.color='var(--text)';}).catch(()=>{se.innerHTML=svgIcon('ic-box')+' الحجم: غير معروف';});$('dlConfirmMulti').checked=false;$('dlConfirmBtnText').textContent='تنزيل';openModalUniversal('downloadConfirmModal');}
async function getFileSize(url){const c=fileSizeCache[url];if(c&&(Date.now()-c.ts)<3600000)return c.size;try{const r=await fetchWithTimeout(url,{method:'HEAD',timeout:5000});if(r.ok){const s=parseInt(r.headers.get('content-length'))||0;fileSizeCache[url]={size:s,ts:Date.now()};return s;}}catch(e){}return 0;}
function getFileSizeFromCache(url){const c=fileSizeCache[url];if(c&&(Date.now()-c.ts)<3600000)return c.size;return 0;}
function downloadWithProgress(url,onProgress,startByte,did){return new Promise((res,rej)=>{const xhr=new XMLHttpRequest();activeDownloads[did]={xhr:xhr,status:'downloading'};activeXHR=xhr;xhr.open('GET',url,true);xhr.responseType='blob';xhr.onprogress=e=>{if(e.lengthComputable)onProgress(Math.round((e.loaded/e.total)*100));};xhr.onload=()=>{delete activeDownloads[did];activeXHR=null;if(xhr.status===200||xhr.status===206){const b=xhr.response;res({blob:b,size:b.size});}else rej(new Error('فشل'));};xhr.onerror=()=>{delete activeDownloads[did];activeXHR=null;rej(new Error('شبكة'));};xhr.onabort=()=>{delete activeDownloads[did];activeXHR=null;rej(new Error('تم الإلغاء'));};xhr.send();});}
function updateDownloadProgress(rid,idx,pct){if(!downloadProgress[rid])downloadProgress[rid]={};downloadProgress[rid][idx]=pct;renderAllSurahs(true);}
function clearDownloadProgress(rid,idx){if(downloadProgress[rid])delete downloadProgress[rid][idx];renderAllSurahs(true);}
function abortCurrentDownload(){if(activeXHR){activeXHR.abort();activeXHR=null;}}
async function startNewDownload(rid,idx){const did=rid+'_'+idx;if(activeDownloads[did]){toastWarning('التحميل بدأ بالفعل');return;}const url=getReaderUrl(rid,idx);if(!url){toastError('تعذر الحصول على رابط السورة');return;}try{const c=await caches.open('quran-audio'),cached=await c.match(url);if(cached){toastInfo('السورة موجودة بالفعل');if(!downloaded[rid])downloaded[rid]={};try{const b=await cached.blob();downloaded[rid][idx]={downloaded:true,size:b.size,date:new Date().toISOString(),lastPlayedAt:null};}catch(e){downloaded[rid][idx]={downloaded:true,size:0,date:new Date().toISOString(),lastPlayedAt:null};}debouncedSaveState();renderAllSurahs(true);return;}}catch(e){}const sn=SN[idx];try{updateDownloadProgress(rid,idx,0);toastInfo('جاري تنزيل: '+sn);const result=await downloadWithProgress(url,pct=>updateDownloadProgress(rid,idx,pct),0,did);const b=result.blob,size=result.size||b.size;const c=await caches.open('quran-audio');await c.put(url,new Response(b));if(!downloaded[rid])downloaded[rid]={};downloaded[rid][idx]={downloaded:true,size:size,date:new Date().toISOString(),lastPlayedAt:null};clearDownloadProgress(rid,idx);debouncedSaveState();renderAllSurahs(true);toastSuccess('تم تنزيل "'+sn+'" ('+formatSize(size)+')');}catch(e){if(e.message==='تم الإلغاء')toastInfo('تم إلغاء تنزيل: '+sn);else toastError('فشل تنزيل: '+sn);clearDownloadProgress(rid,idx);delete activeDownloads[did];}}
async function downloadSelectedSurahs(){const checks=document.querySelectorAll('#selectionGrid input[type="checkbox"]:checked');const sel=[];checks.forEach(cb=>{const idx=parseInt(cb.dataset.idx),isDl=downloaded[currentReader]?.[idx]?.downloaded;if(!isDl)sel.push(idx);});if(sel.length===0){toastWarning('لا توجد سور جديدة للتنزيل');return;}closeModalUniversal('surahSelectionModal');await new Promise(r=>setTimeout(r,150));showDownloadProgressOverlay(sel);}
function showDownloadProgressOverlay(surahIndices){const o=$('downloadProgressOverlay');if(!o)return;const rn=getReaderName(currentReader);$('dlProgressReader').textContent=rn;$('dlProgressMain').textContent='0%';$('dlProgressMainBar').style.width='0%';$('dlProgressCount').textContent='0/'+surahIndices.length;$('dlCurrentSurah').textContent='جاري التجهيز...';$('dlCurrentSurahBar').style.width='0%';$('dlCurrentSurahPct').textContent='0%';o.style.display='flex';o.classList.add('show');lockBodyScroll();pushWindow('downloadProgressOverlay');setTimeout(()=>startMultipleDownloads(surahIndices),100);}
async function startMultipleDownloads(surahIndices){if(isDownloadingMultiple){toastWarning('جاري التنزيل بالفعل');return;}isDownloadingMultiple=true;downloadCancel=false;const rid=currentReader,total=surahIndices.length;let done=0,skipped=0;for(let i=0;i<surahIndices.length;i++){if(downloadCancel)break;const idx=surahIndices[i],did=rid+'_'+idx;if(activeDownloads[did]){toastWarning('التحميل جارٍ بالفعل');done++;continue;}const url=getReaderUrl(rid,idx);if(!url){done++;skipped++;continue;}const isDl=downloaded[rid]?.[idx]?.downloaded;if(isDl){done++;continue;}$('dlProgressMain').textContent=Math.round((done/total)*100)+'%';$('dlProgressMainBar').style.width=(done/total)*100+'%';$('dlProgressCount').textContent=done+'/'+total;$('dlCurrentSurah').textContent=SN[idx];try{updateDownloadProgress(rid,idx,0);const result=await downloadWithProgress(url,p=>{updateDownloadProgress(rid,idx,p);$('dlCurrentSurahBar').style.width=p+'%';$('dlCurrentSurahPct').textContent=p+'%';},0,did);const b=result.blob,size=result.size||b.size;const c=await caches.open('quran-audio');await c.put(url,new Response(b));if(!downloaded[rid])downloaded[rid]={};downloaded[rid][idx]={downloaded:true,size:size,date:new Date().toISOString(),lastPlayedAt:null};clearDownloadProgress(rid,idx);debouncedSaveState();done++;renderAllSurahs(true);}catch(e){if(e.message==='تم الإلغاء'){toastInfo('تم إيقاف التنزيل');break;}clearDownloadProgress(rid,idx);delete activeDownloads[did];done++;skipped++;}}isDownloadingMultiple=false;closeModalUniversal('downloadProgressOverlay');unlockBodyScroll();if(!downloadCancel){if(skipped>0)toastSuccess('تم تنزيل '+(done-skipped)+' سورة، تخطي '+skipped);else if(done>0)toastSuccess('تم تنزيل '+done+' سورة بنجاح');}}
function showSurahSelectionModal(initialIdx){const grid=$('selectionGrid');$('selReaderName').textContent=getReaderName(currentReader);grid.innerHTML='';const rid=currentReader;const old=$('selectionInfoBanner');if(old)old.remove();const info=document.createElement('div');info.id='selectionInfoBanner';info.className='selection-info-banner';info.innerHTML=svgIcon('ic-info-circle')+'<div style="flex:1;"><div><strong>معلومة:</strong> يمكن تنزيل السور المتاحة فقط.</div></div>';grid.parentNode.insertBefore(info,grid);for(let i=0;i<TOTAL;i++){const div=document.createElement('div');div.className='selection-item';const isDl=downloaded[rid]?.[i]?.downloaded;const checked=(i===initialIdx)&&!isDl;if(isDl)div.classList.add('downloaded-item');const cbId='sel_cb_'+i;let rh='';if(isDl)rh='<span class="reason-badge" style="color:var(--gold);">'+svgIcon('ic-check-circle')+' مُنزّلة مسبقاً</span>';div.innerHTML='<div class="checkbox-wrapper-12"><div class="cbx"><input type="checkbox" id="'+cbId+'" data-idx="'+i+'" '+(checked?'checked':'')+(isDl?' disabled':'')+'><label for="'+cbId+'"></label><svg width="15" height="14" viewBox="0 0 15 14" fill="none"><path d="M2 8.36364L6.23077 12L13 2"></path></svg></div></div><span class="item-name-text">'+(i+1)+' '+SN[i]+'</span>'+rh;const cb=div.querySelector('input');cb.addEventListener('change',updateSelectionStats);div.addEventListener('click',function(e){if(isDl)return;if(e.target.tagName.toLowerCase()==='input')return;const c=this.querySelector('input');if(!c||c.disabled)return;c.checked=!c.checked;c.dispatchEvent(new Event('change'));});grid.appendChild(div);}$('selTotal').textContent='114';updateSelectionStats();openModalUniversal('surahSelectionModal');}
function updateSelectionStats(){const checked=document.querySelectorAll('#selectionGrid input[type="checkbox"]:checked');$('selCount').textContent=checked.length;const rid=currentReader;let totalSize=0;checked.forEach(cb=>{const idx=parseInt(cb.dataset.idx),url=getReaderUrl(rid,idx);if(url){const s=getFileSizeFromCache(url);if(s>0)totalSize+=s;}});$('selTotalSize').textContent=formatSize(totalSize)||'0';}
function showDeleteConfirm(idx){if(idx<0||idx>113){toastError('رقم سورة غير صحيح');return;}confirmIdx=idx;const rid=currentReader,rn=getReaderName(rid),sn=SN[idx]||'سورة '+(idx+1);const fs=downloaded[rid]?.[idx]?.size||0,se=$('dlDeleteSize');se.textContent='جاري حساب الحجم...';se.style.color='var(--text-secondary)';$('dlDeleteSurah').textContent=sn;$('dlDeleteReader').textContent='القارئ: '+rn;if(fs>0){se.innerHTML=svgIcon('ic-box')+' الحجم: <strong>'+formatSize(fs)+'</strong>';se.style.color='var(--text)';}else se.textContent='الحجم: غير معروف';$('dlDeleteMulti').checked=false;$('dlDeleteBtnText').textContent='تأكيد الحذف';openModalUniversal('deleteConfirmModal');}
function showDeleteSelectionModal(){const grid=$('deleteSelectionGrid');$('delSelReaderName').textContent=getReaderName(currentReader);grid.innerHTML='';const rid=currentReader;let has=false;for(let i=0;i<TOTAL;i++){const isDl=downloaded[rid]?.[i]?.downloaded;if(isDl)has=true;const div=document.createElement('div');div.className='selection-item'+(isDl?'':' downloaded-item');const fs=isDl?(downloaded[rid][i].size||0):0,st=fs>0?formatSize(fs):'';const cbId='del_cb_'+i;div.innerHTML='<div class="checkbox-wrapper-12"><div class="cbx"><input type="checkbox" id="'+cbId+'" data-idx="'+i+'" '+(isDl?'':'disabled')+'><label for="'+cbId+'"></label><svg width="15" height="14" viewBox="0 0 15 14" fill="none"><path d="M2 8.36364L6.23077 12L13 2"></path></svg></div></div><span>'+(i+1)+' '+SN[i]+'</span>'+(isDl?'<span style="font-size:calc(.6rem*var(--text-scale));color:var(--gold);margin-right:auto;">'+svgIcon('ic-check-circle')+' '+st+'</span>':'<span style="font-size:calc(.6rem*var(--text-scale));color:var(--text-secondary);">'+svgIcon('ic-times-circle')+' غير محملة</span>');const cb=div.querySelector('input');cb.addEventListener('change',updateDeleteSelectionStats);div.addEventListener('click',function(e){if(e.target.tagName.toLowerCase()==='input')return;const c=this.querySelector('input');if(!c||c.disabled)return;c.checked=!c.checked;c.dispatchEvent(new Event('change'));});grid.appendChild(div);}if(!has){toastWarning('لا توجد سور محملة للحذف');return;}$('delSelTotal').textContent='114';updateDeleteSelectionStats();openModalUniversal('deleteSelectionModal');}
function updateDeleteSelectionStats(){const checked=document.querySelectorAll('#deleteSelectionGrid input[type="checkbox"]:checked');$('delSelCount').textContent=checked.length;const rid=currentReader;let ts=0;checked.forEach(cb=>{const idx=parseInt(cb.dataset.idx);if(downloaded[rid]?.[idx])ts+=downloaded[rid][idx].size||0;});$('delSelTotalSize').textContent=ts>0?formatSize(ts):'0';}
function showDeleteVerificationModal(){const checked=document.querySelectorAll('#deleteSelectionGrid input[type="checkbox"]:checked');if(checked.length===0){toastWarning('لم تختر أي سورة للحذف');return;}closeModalUniversal('deleteSelectionModal');deleteCaptchaCode=generateRandomCode();$('deleteCaptchaCode').textContent=deleteCaptchaCode;$('deleteCaptchaInput').value='';$('deleteVerifyError').style.display='none';$('deleteVerifyCount').textContent=checked.length;openModalUniversal('deleteVerifyModal');setTimeout(()=>$('deleteCaptchaInput').focus(),300);}
function executeDelete(){const input=$('deleteCaptchaInput').value.trim();if(input!==deleteCaptchaCode){$('deleteVerifyError').style.display='block';$('deleteCaptchaInput').value='';deleteCaptchaCode=generateRandomCode();$('deleteCaptchaCode').textContent=deleteCaptchaCode;setTimeout(()=>$('deleteVerifyError').style.display='none',3000);return;}closeModalUniversal('deleteVerifyModal');const checked=document.querySelectorAll('#deleteSelectionGrid input[type="checkbox"]:checked');const rid=currentReader;let deleted=0,ts=0;checked.forEach(cb=>{const idx=parseInt(cb.dataset.idx),sn=SN[idx],url=getReaderUrl(rid,idx);if(url)caches.open('quran-audio').then(c=>c.delete(url));if(downloaded[rid]?.[idx]){ts+=downloaded[rid][idx].size||0;delete downloaded[rid][idx];deleted++;}});if(downloaded[rid]&&Object.keys(downloaded[rid]).length===0)delete downloaded[rid];debouncedSaveState();renderAllSurahs(true);const st=ts>0?formatSize(ts):'';toastSuccess('تم حذف '+deleted+' سورة'+(st?' ('+st+')':''));}
function stopSleepTimer(){if(sleepTimerInterval){clearInterval(sleepTimerInterval);sleepTimerInterval=null;}sleepTimerRemaining=0;$('sleepTimerIndicator').style.display='none';$('sleepTimerDisplay').textContent='00:00';$('sleepTimerBtn').innerHTML=svgIcon('ic-hourglass');}
function updateTimerDisplay(){const m=Math.floor(sleepTimerRemaining/60),s=sleepTimerRemaining%60;$('sleepTimerDisplay').textContent=String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');}
function startSleepTimer(min,sec){stopSleepTimer();const t=(min*60)+sec;if(t<1){toastWarning('الحد الأدنى ثانية واحدة');return;}sleepTimerRemaining=t;$('sleepTimerIndicator').style.display='flex';updateTimerDisplay();toastInfo('تم ضبط مؤقت النوم');sleepTimerInterval=setInterval(()=>{sleepTimerRemaining--;updateTimerDisplay();if(sleepTimerRemaining<=0){stopSleepTimer();toastInfo('انتهى وقت المؤقت');if(audio.src&&!audio.paused){audio.pause();isPlaying=false;updatePlayerUI();}if(radioAudio.src&&!radioAudio.paused){radioAudio.pause();isRadio=false;isRadioPlaying=false;updateRadioBtnUI();}}},1000);}
function updateBannerToggleBtn(){const b=$('bannerToggleBtn'),bn=$('randomAyahBanner');if(!b||!bn)return;const v=bn.classList.contains('visible');b.style.display=v?'none':'';}
function showBannerFromBtn(){const b=$('randomAyahBanner');if(!b)return;if(b.classList.contains('visible'))b.classList.remove('visible');else showRandomAyah();updateBannerToggleBtn();}
function showRandomAyah(){const b=$('randomAyahBanner'),te=$('bannerAyahText'),rb=$('bannerReadBtn');if(!b||!te||!rb)return;if(b.classList.contains('visible'))b.classList.remove('visible');if(!quranTexts||quranTexts.length===0){te.innerHTML='<div style="display:flex;align-items:center;justify-content:center;gap:.5rem;padding:1rem;"><div class="loading-spinner"></div><span>جاري تحميل آية...</span></div>';b.classList.add('visible');loadQuranTexts().then(()=>{if(quranTexts&&quranTexts.length>0)showRandomAyah();else te.textContent='تعذر تحميل الآية';});return;}const si=Math.floor(Math.random()*quranTexts.length),s=quranTexts[si];if(!s||!s.ayahs||s.ayahs.length===0)return;const ai=Math.floor(Math.random()*s.ayahs.length),a=s.ayahs[ai];if(!a||!a.text)return;te.innerHTML='<div class="banner-inner-wrap"><div class="banner-hint-title">'+svgIcon('ic-comment-dots')+' همسة قرآنية :</div><div class="banner-ayah-content">"'+escapeHtml(a.text)+'"</div><span class="banner-ayah-ref">'+svgIcon('ic-book-open')+' '+escapeHtml(s.name)+' (الآية '+a.number+')</span></div><div class="banner-divider"></div>';b.classList.add('visible');rb.dataset.surahIdx=si;rb.dataset.ayahNum=a.number;updateBannerToggleBtn();}
function toggleSideMenu(open){const o=$('sideMenuOverlay'),m=$('sideMenu');if(!o||!m)return;if(open){o.classList.add('show');m.classList.add('open');pushWindow('sideMenu');history.pushState({modal:'sideMenu',level:windowStack.length},'');history.pushState({modal:'sideMenu',level:windowStack.length},'');}else{o.classList.remove('show');m.classList.remove('open');windowStack=windowStack.filter(w=>w!=='sideMenu');}}
function openFilterModal(){const m=$('filterModal');if(!m)return;let ca='all';document.querySelectorAll('.filter-option').forEach(b=>{if(b.classList.contains('active'))ca=b.dataset.filter;});document.querySelectorAll('.filter-modal-option').forEach(b=>b.classList.toggle('active',b.dataset.filter===ca));openModalUniversal('filterModal');}
function selectFilterOption(f){currentFilter=f;document.querySelectorAll('.filter-option').forEach(b=>b.classList.toggle('active',b.dataset.filter===f));document.querySelectorAll('.filter-modal-option').forEach(b=>b.classList.toggle('active',b.dataset.filter===f));closeModalUniversal('filterModal');filterSurahs(f);}
function getDownloadStats(){const rid=currentReader;let c=0,s=0;if(downloaded[rid])for(const i in downloaded[rid])if(downloaded[rid][i]?.downloaded){c++;if(downloaded[rid][i].size)s+=downloaded[rid][i].size;}return{count:c,size:s};}
function openStatsModal(){const content=$('statsModalContent');if(!content)return;const rid=currentReader;const ds=getDownloadStats(),st=ds.size>0?formatSize(ds.size):'0',rn=getReaderName(currentReader);let h='<div class="sm-reader-box">'+svgIcon('ic-microphone')+'<div class="sm-reader-info"><div class="sm-reader-label">القارئ الحالي</div><div class="sm-reader-name">'+escapeHtml(rn)+'</div></div></div><div class="sm-stats-grid"><div class="sm-stat-card"><div class="sm-stat-value">'+ds.count+'</div><div class="sm-stat-label">مُنزّل</div></div><div class="sm-stat-card"><div class="sm-stat-value">'+R.length+'</div><div class="sm-stat-label">قارئ</div></div><div class="sm-stat-card"><div class="sm-stat-value">'+st+'</div><div class="sm-stat-label">الحجم</div></div></div>';content.innerHTML=h;openModalUniversal('statsModal');}
function toggleFavSurah(idx){const i=favSurahs.indexOf(idx);if(i>=0){favSurahs.splice(i,1);toastSuccess('تم إزالة من المفضلة');}else{favSurahs.push(idx);toastSuccess('تمت الإضافة إلى المفضلة');}debouncedSaveState();const card=document.querySelector('.surah-card[data-idx="'+idx+'"]');if(card){const fb=card.querySelector('.fav-btn');if(fb){fb.classList.toggle('active',favSurahs.indexOf(idx)!==-1);fb.innerHTML=svgIcon(favSurahs.indexOf(idx)!==-1?'ic-star-fill':'ic-star');}}if(currentSurah===idx){updatePlayerFavButton();const pb=$('playerFavBtn');if(pb){pb.classList.remove('animate');void pb.offsetWidth;pb.classList.add('animate');setTimeout(()=>pb.classList.remove('animate'),1000);}}}
const manageState={activeTab:'downloads',selectedReaders:{},selectedSurahs:{},sizeFilterActive:false,sizeFilterMinMB:20,oldFilterActive:false,unusedFilterActive:false,favSelectedReaders:{},favSelectedSurahs:{},tafsirSelected:{}};
function openManageData(){const m=$('manageDataModal');if(!m)return;manageState.activeTab='downloads';manageState.selectedReaders={};manageState.selectedSurahs={};manageState.sizeFilterActive=false;manageState.oldFilterActive=false;manageState.unusedFilterActive=false;manageState.favSelectedReaders={};manageState.favSelectedSurahs={};manageState.tafsirSelected={};updateManageOverview();switchManageTab('downloads');openModalUniversal('manageDataModal');setTimeout(()=>{const i=$('factoryConfirmInput');if(i)i.value='';},100);}
function updateManageOverview(){const ovR=$('ovReadersCount');if(ovR)ovR.textContent=R.length;let dc=0;for(const rid in downloaded){if(!downloaded[rid])continue;for(const s in downloaded[rid])if(downloaded[rid][s]?.downloaded)dc++;}const ovD=$('ovDownloadsInfo');if(ovD)ovD.textContent=dc;const o=$('ovQuranStatus');if(o)o.textContent='—';const o2=$('ovTafsirInfo');if(o2)o2.textContent='0';}
function switchManageTab(t){manageState.activeTab=t;document.querySelectorAll('.manage-tabs .tab-btn').forEach(b=>b.classList.toggle('active',b.dataset.tab===t));document.querySelectorAll('.manage-tab-content').forEach(c=>c.classList.remove('active'));const target=$('tab-'+t);if(target)target.classList.add('active');if(t==='downloads')renderDownloadsTab();else if(t==='favorites')renderFavoritesTab();else if(t==='quran')renderQuranTab();else if(t==='tafsir')renderTafsirTab();}
function getReaderDownloadStats(rid){let c=0,s=0;if(downloaded[rid])for(const i in downloaded[rid]){const d=downloaded[rid][i];if(d?.downloaded){c++;s+=d.size||0;}}return{count:c,size:s};}
function renderDownloadsTab(){const list=$('downloadsList');if(!list)return;const rdl=[];for(const rid in downloaded){const st=getReaderDownloadStats(rid);if(st.count>0)rdl.push({id:rid,name:getReaderName(rid),count:st.count,size:st.size});}rdl.sort((a,b)=>b.size-a.size);if(rdl.length===0){list.innerHTML='<div class="manage-empty">'+svgIcon('ic-download')+'لا توجد سور مُنزّلة</div>';updateDownloadsSelection();return;}let h='';rdl.forEach(r=>{const isSel=!!manageState.selectedReaders[r.id],sz=r.size>0?formatSize(r.size):'غير معروف';h+='<div class="manage-reader-row'+(isSel?' selected':'')+'" data-reader="'+r.id+'"><div class="manage-reader-header"><span class="r-cbx"><div class="checkbox-wrapper-12"><div class="cbx"><input type="checkbox" id="rd_'+r.id+'" '+(isSel?'checked':'')+'><label for="rd_'+r.id+'"></label><svg width="15" height="14" viewBox="0 0 15 14" fill="none"><path d="M2 8.36364L6.23077 12L13 2"></path></svg></div></div></span><div class="r-info"><div class="r-name">'+escapeHtml(r.name)+'</div><div class="r-meta">'+r.count+' سورة • '+sz+'</div></div><button class="r-expand" data-reader="'+r.id+'">'+svgIcon('ic-chevron-down')+'</button></div><div class="manage-reader-surahs" id="surahs_'+r.id+'"></div></div>';});list.innerHTML=h;list.querySelectorAll('.manage-reader-row').forEach(row=>{const rid=row.dataset.reader,cb=row.querySelector('input[type="checkbox"]');if(cb)cb.addEventListener('change',function(e){e.stopPropagation();if(this.checked){manageState.selectedReaders[rid]=true;row.classList.add('selected');}else{delete manageState.selectedReaders[rid];row.classList.remove('selected');if(manageState.selectedSurahs[rid])delete manageState.selectedSurahs[rid];}updateDownloadsSelection();});const eb=row.querySelector('.r-expand');if(eb)eb.addEventListener('click',function(e){e.stopPropagation();this.classList.toggle('open');const sd=$('surahs_'+rid);if(sd){sd.classList.toggle('open');if(sd.classList.contains('open')&&!sd.innerHTML)renderReaderSurahs(rid,sd);}});});updateDownloadsSelection();}
function renderReaderSurahs(rid,container){if(!downloaded[rid])return;const items=[];for(const idx in downloaded[rid]){const d=downloaded[rid][idx];if(d?.downloaded)items.push({idx:parseInt(idx),size:d.size||0});}items.sort((a,b)=>a.idx-b.idx);let h='';items.forEach(it=>{const isSel=manageState.selectedSurahs[rid]?.[it.idx],st=it.size>0?formatSize(it.size):'';h+='<div class="manage-surah-item'+(isSel?' selected':'')+'" data-idx="'+it.idx+'"><div class="checkbox-wrapper-12"><div class="cbx"><input type="checkbox" id="s_'+rid+'_'+it.idx+'" '+(isSel?'checked':'')+'><label for="s_'+rid+'_'+it.idx+'"></label><svg width="15" height="14" viewBox="0 0 15 14" fill="none"><path d="M2 8.36364L6.23077 12L13 2"></path></svg></div></div><span class="s-name">'+(it.idx+1)+'. '+SN[it.idx]+'</span><span class="s-size">'+st+'</span></div>';});container.innerHTML=h;container.querySelectorAll('.manage-surah-item').forEach(item=>{const idx=parseInt(item.dataset.idx),cb=item.querySelector('input[type="checkbox"]');if(cb)cb.addEventListener('change',function(){if(!manageState.selectedSurahs[rid])manageState.selectedSurahs[rid]={};if(this.checked){manageState.selectedSurahs[rid][idx]=true;item.classList.add('selected');}else{delete manageState.selectedSurahs[rid][idx];item.classList.remove('selected');}updateDownloadsSelection();});});}
function updateDownloadsSelection(){let tc=0,ts=0;for(const rid in manageState.selectedReaders){if(!manageState.selectedReaders[rid])continue;if(manageState.selectedSurahs[rid]&&Object.keys(manageState.selectedSurahs[rid]).length>0){for(const idx in manageState.selectedSurahs[rid])if(downloaded[rid]?.[idx]){tc++;ts+=downloaded[rid][idx].size||0;}}else if(downloaded[rid]){for(const i in downloaded[rid])if(downloaded[rid][i]?.downloaded){tc++;ts+=downloaded[rid][i].size||0;}}}$('dlSelectedCount').textContent=tc;$('dlSelectedSize').textContent=formatSize(ts);}
function applySizeFilter(mb){manageState.sizeFilterActive=true;manageState.sizeFilterMinMB=mb;const min=mb*1024*1024;manageState.selectedReaders={};manageState.selectedSurahs={};let m=0,ms=0;for(const rid in downloaded){if(!downloaded[rid])continue;for(const idx in downloaded[rid]){const d=downloaded[rid][idx];if(d?.downloaded&&(d.size||0)>=min){if(!manageState.selectedReaders[rid])manageState.selectedReaders[rid]=true;if(!manageState.selectedSurahs[rid])manageState.selectedSurahs[rid]={};manageState.selectedSurahs[rid][idx]=true;m++;ms+=d.size||0;}}}const p=$('dlSizePreview');if(p)p.innerHTML='السور المطابقة: <strong>'+m+'</strong> سورة • الحجم: <strong>'+formatSize(ms)+'</strong>';renderDownloadsTab();}
function applyOldFilter(days){manageState.oldFilterActive=true;manageState.selectedReaders={};manageState.selectedSurahs={};const th=Date.now()-(days*24*60*60*1000);let m=0,ms=0;for(const rid in downloaded){if(!downloaded[rid])continue;for(const idx in downloaded[rid]){const d=downloaded[rid][idx];if(d?.downloaded&&d.date){const t=new Date(d.date).getTime();if(t<th){if(!manageState.selectedReaders[rid])manageState.selectedReaders[rid]=true;if(!manageState.selectedSurahs[rid])manageState.selectedSurahs[rid]={};manageState.selectedSurahs[rid][idx]=true;m++;ms+=d.size||0;}}}}toastInfo('تم تحديد '+m+' سورة قديمة ('+formatSize(ms)+')');renderDownloadsTab();}
function applyUnusedFilter(){manageState.unusedFilterActive=true;manageState.selectedReaders={};manageState.selectedSurahs={};let m=0,ms=0;for(const rid in downloaded){if(!downloaded[rid])continue;for(const idx in downloaded[rid]){const d=downloaded[rid][idx];if(d?.downloaded&&!d.lastPlayedAt){if(!manageState.selectedReaders[rid])manageState.selectedReaders[rid]=true;if(!manageState.selectedSurahs[rid])manageState.selectedSurahs[rid]={};manageState.selectedSurahs[rid][idx]=true;m++;ms+=d.size||0;}}}toastInfo('تم تحديد '+m+' سورة غير مستخدمة ('+formatSize(ms)+')');renderDownloadsTab();}
async function executeDownloadsDelete(){const td=[];for(const rid in manageState.selectedReaders){if(!manageState.selectedReaders[rid])continue;if(manageState.selectedSurahs[rid]&&Object.keys(manageState.selectedSurahs[rid]).length>0){for(const idx in manageState.selectedSurahs[rid])if(downloaded[rid]?.[idx])td.push({readerId:rid,idx:parseInt(idx)});}else if(downloaded[rid]){for(const i in downloaded[rid])if(downloaded[rid][i]?.downloaded)td.push({readerId:rid,idx:parseInt(i)});}}if(td.length===0){toastWarning('لم يتم تحديد أي سور للحذف');return;}const c=await caches.open('quran-audio');let ts=0;for(const it of td){const url=getReaderUrl(it.readerId,it.idx);if(url){try{await c.delete(url);}catch(e){}}if(downloaded[it.readerId]?.[it.idx]){ts+=downloaded[it.readerId][it.idx].size||0;delete downloaded[it.readerId][it.idx];}}for(const rid in downloaded)if(downloaded[rid]&&Object.keys(downloaded[rid]).length===0)delete downloaded[rid];debouncedSaveState();renderDownloadsTab();updateManageOverview();renderAllSurahs(true);toastSuccess('تم حذف '+td.length+' سورة ('+formatSize(ts)+')');manageState.selectedReaders={};manageState.selectedSurahs={};manageState.sizeFilterActive=false;manageState.oldFilterActive=false;manageState.unusedFilterActive=false;}
function renderFavoritesTab(){const rl=$('favReadersList'),sl=$('favSurahsList');if(!rl||!sl)return;if(favReaders.length===0)rl.innerHTML='<div class="manage-empty">'+svgIcon('ic-star')+'لا يوجد قراء مفضلون</div>';else{let h='';favReaders.forEach(rid=>{const isSel=!!manageState.favSelectedReaders[rid];h+='<div class="manage-surah-item'+(isSel?' selected':'')+'" data-reader="'+rid+'"><div class="checkbox-wrapper-12"><div class="cbx"><input type="checkbox" id="fr_'+rid+'" '+(isSel?'checked':'')+'><label for="fr_'+rid+'"></label><svg width="15" height="14" viewBox="0 0 15 14" fill="none"><path d="M2 8.36364L6.23077 12L13 2"></path></svg></div></div><span class="s-name">'+escapeHtml(getReaderName(rid))+'</span></div>';});rl.innerHTML=h;rl.querySelectorAll('.manage-surah-item').forEach(item=>{const rid=item.dataset.reader,cb=item.querySelector('input[type="checkbox"]');if(cb)cb.addEventListener('change',function(){if(this.checked){manageState.favSelectedReaders[rid]=true;item.classList.add('selected');}else{delete manageState.favSelectedReaders[rid];item.classList.remove('selected');}updateFavSelection();});});}if(favSurahs.length===0)sl.innerHTML='<div class="manage-empty">'+svgIcon('ic-bookmark')+'لا توجد سور مفضلة</div>';else{let h='';favSurahs.forEach(idx=>{const isSel=!!manageState.favSelectedSurahs[idx];h+='<div class="manage-surah-item'+(isSel?' selected':'')+'" data-idx="'+idx+'"><div class="checkbox-wrapper-12"><div class="cbx"><input type="checkbox" id="fs_'+idx+'" '+(isSel?'checked':'')+'><label for="fs_'+idx+'"></label><svg width="15" height="14" viewBox="0 0 15 14" fill="none"><path d="M2 8.36364L6.23077 12L13 2"></path></svg></div></div><span class="s-name">'+(idx+1)+'. '+SN[idx]+'</span></div>';});sl.innerHTML=h;sl.querySelectorAll('.manage-surah-item').forEach(item=>{const idx=parseInt(item.dataset.idx),cb=item.querySelector('input[type="checkbox"]');if(cb)cb.addEventListener('change',function(){if(this.checked){manageState.favSelectedSurahs[idx]=true;item.classList.add('selected');}else{delete manageState.favSelectedSurahs[idx];item.classList.remove('selected');}updateFavSelection();});});}updateFavSelection();}
