async function executeFavoritesDelete(){const rids=Object.keys(manageState.favSelectedReaders),sids=Object.keys(manageState.favSelectedSurahs).map(Number);if(rids.length===0&&sids.length===0){toastWarning('لم يتم تحديد أي عنصر');return;}rids.forEach(r=>{const p=favReaders.indexOf(r);if(p!==-1)favReaders.splice(p,1);});sids.forEach(i=>{const p=favSurahs.indexOf(i);if(p!==-1)favSurahs.splice(p,1);});debouncedSaveState();updateFavReaderStar();renderReaderList();renderFavoritesTab();updateManageOverview();renderAllSurahs(true);toastSuccess('تم حذف '+(rids.length+sids.length)+' عنصر');manageState.favSelectedReaders={};manageState.favSelectedSurahs={};}
