async function executeFactoryReset(){const input=$('factoryConfirmInput');if(!input||input.value.trim()!=='نعم حذف نهائي'){toastWarning('يجب كتابة "نعم حذف نهائي" للتأكيد');return;}const dDl=$('factoryResetDownloads').checked,dFv=$('factoryResetFavs').checked,dQ=$('factoryResetQuran').checked,dH=$('factoryResetHelp').checked,dS=$('factoryResetSettings').checked;if(!dDl&&!dFv&&!dQ&&!dH&&!dS){toastWarning('يرجى تحديد خيار واحد على الأقل');return;}showManageVerify('تأكيد إعادة ضبط المصنع',async()=>{if(dDl){try{const c=await caches.open('quran-audio'),ks=await c.keys();for(const k of ks)await c.delete(k);}catch(e){}downloaded={};localStorage.removeItem('downloadedSurahs');}if(dFv){favSurahs=[];favReaders=['abdulbaset_murattal','abdulbaset_mujawwad','minsh_murattal','minsh_mujawwad','maher_murattal'].filter(id=>getReader(id));localStorage.removeItem('favSurahs');localStorage.removeItem('favReaders');}if(dQ){quranTexts=null;}if(dH){localStorage.removeItem('showHelp');localStorage.removeItem('welcomeShown');}if(dS){localStorage.removeItem('darkMode');localStorage.removeItem('accentColor');localStorage.removeItem('quranFont');localStorage.removeItem('quranFontSize');localStorage.removeItem('textScale');localStorage.removeItem('displayScale');localStorage.removeItem('mushafFont');localStorage.removeItem('mushafLineHeight');localStorage.removeItem('mushafTheme');localStorage.removeItem('mushafViewMode');localStorage.removeItem('mushafFocusMode');localStorage.removeItem('tafsirSource');localStorage.removeItem('playerPinned');darkMode=false;currentColor='gold';currentFont='system';fontsize=1.5;mushafFont='default';mushafLineHeight=2.75;mushafTheme='auto';mushafViewMode='pages';mushafFocusMode=false;tafsirSource='mizan';isPlayerPinned=false;applyColor('gold');applyTheme('light');loadFontFamily('system');}localStorage.removeItem('lastPlay');localStorage.removeItem('lastReading');localStorage.removeItem('sessions');debouncedSaveState();toastSuccess('تمت إعادة الضبط بنجاح');closeModalUniversal('manageDataModal');renderAllSurahs(true);renderReaderList();updateFavReaderStar();updateManageOverview();});}
function showManageVerify(message,onConfirm){manageCaptchaCode=generateRandomCode();const ce=$('manageCaptchaCode'),ie=$('manageCaptchaInput'),me=$('manageVerifyMessage'),ee=$('manageVerifyError');if(ce)ce.textContent=manageCaptchaCode;if(ie)ie.value='';if(me)me.textContent=message||'أدخل الرمز التالي لتأكيد العملية:';if(ee)ee.style.display='none';managePendingAction=onConfirm;openModalUniversal('manageVerifyModal');setTimeout(()=>{if(ie)ie.focus();},300);}
